MOTIF_NAME = 'knight_on_outpost'
MOTIF_DESCRIPTION = 'The side to move has a knight on a square that cannot be attacked by opponent pawns and is protected by a friendly pawn.'
def motif(fen: str) -> bool:
    board = chess.Board(fen)
    stm = board.turn
    opp = not stm

    # Precompute opponent pawn squares
    opp_pawn_squares = board.pieces(chess.PAWN, opp)

    # Precompute stm pawn squares
    stm_pawn_squares = board.pieces(chess.PAWN, stm)

    # Helper to check if a square is attacked by any opponent pawn
    def square_attacked_by_opp_pawn(sq):
        file = chess.square_file(sq)
        rank = chess.square_rank(sq)
        if stm == chess.WHITE:
            # Black pawns attack from rank+1
            if rank <= 6:
                attack_rank = rank + 1
                if file > 0:
                    if chess.square(file - 1, attack_rank) in opp_pawn_squares:
                        return True
                if file < 7:
                    if chess.square(file + 1, attack_rank) in opp_pawn_squares:
                        return True
        else:
            # White pawns attack from rank-1
            if rank >= 1:
                attack_rank = rank - 1
                if file > 0:
                    if chess.square(file - 1, attack_rank) in opp_pawn_squares:
                        return True
                if file < 7:
                    if chess.square(file + 1, attack_rank) in opp_pawn_squares:
                        return True
        return False

    # Check each stm knight
    for knight_sq in board.pieces(chess.KNIGHT, stm):
        if square_attacked_by_opp_pawn(knight_sq):
            continue
        # Check if defended by at least one stm pawn
        file = chess.square_file(knight_sq)
        rank = chess.square_rank(knight_sq)
        defended = False
        if stm == chess.WHITE:
            # White pawns defend from rank-1
            if rank >= 1:
                def_rank = rank - 1
                if file > 0 and chess.square(file - 1, def_rank) in stm_pawn_squares:
                    defended = True
                if file < 7 and chess.square(file + 1, def_rank) in stm_pawn_squares:
                    defended = True
        else:
            # Black pawns defend from rank+1
            if rank <= 6:
                def_rank = rank + 1
                if file > 0 and chess.square(file - 1, def_rank) in stm_pawn_squares:
                    defended = True
                if file < 7 and chess.square(file + 1, def_rank) in stm_pawn_squares:
                    defended = True
        if defended:
            # Additional condition: knight is on opponent's half or center
            if stm == chess.WHITE and rank >= 4:
                return True
            if stm == chess.BLACK and rank <= 3:
                return True
            # Also consider knights on the 4th rank for both colors
            if rank == 3 or rank == 4:
                return True
    return False
